25:   placements: null,
26:   error: null,
27: };
28: 
29: let shapesRequest: Promise<TractShapes> | null = null;
30: 
31: /** The tract shapes, fetched once per page load. */
32: function loadShapes() {
33:   shapesRequest ??= fetch("/api/tracts").then(async (r) => {
34:     if (!r.ok) throw new Error(`Could not load the tract shapes (HTTP ${r.status})`);
35:     const shapes: TractShapes = await r.json();
36:     registerNeighborhoods(shapes);
37:     return shapes;
38:   });
39:   return shapesRequest;
40: }
41: 
42: /** Identifies a campaign within one run; campaigns are only ever appended, so the index is stable. */
43: export function campaignId(campaign: Campaign, index: number) {
44:   return `${index}|${campaign.sourceUrl}|${campaign.title}`;
45: }
46: 
47: export function campaignsOf(events: AgentEvent[]): Campaign[] {
48:   return events.flatMap((e) => (e.type === "campaign" ? [e.campaign] : []));
49: }
50: 
51: export function competitorsOf(events: AgentEvent[]): Competitor[] {
52:   return events.flatMap((e) => (e.type === "competitor" ? [e.competitor] : []));
53: }
54: 
55: export function useAudienceRun() {
56:   const [run, setRun] = useState<RunState | null>(null);
57:   const controller = useRef<AbortController | null>(null);
58: 
59:   const start = useCallback(async (brief: Brief) => {
60:     controller.current?.abort();
61:     const ctrl = new AbortController();
62:     controller.current = ctrl;
63:     setRun(EMPTY);
64:     const update = (patch: (r: RunState) => Partial<RunState>) => {
65:       if (!ctrl.signal.aborted) setRun((r) => (r ? { ...r, ...patch(r) } : r));
66:     };
67: 
68:     try {
69:       const events: AgentEvent[] = [];
70:       const agent = (async () => {
71:         for await (const event of runCompetitorAgent(brief, ctrl.signal)) {
72:           events.push(event);
73:           update((r) => ({ events: [...r.events, event] }));
74:         }
75:         update(() => ({ agentDone: true }));
76:       })();
77:       const [shapes, fit] = await Promise.all([
78:         loadShapes().then((shapes) => {
79:           update(() => ({ shapes }));
80:           return shapes;
81:         }),
82:         scoreAudience(brief).then((fit) => {
83:           update(() => ({ fit }));
84:           return fit;
85:         }),
86:       ]);
87: 
88:       const rankPlacements = async () => {
89:         if (ctrl.signal.aborted) return;
90:         const campaigns = campaignsOf(events);
91:         const layers = computeLayers(shapes, fit, campaigns);
92:         const found = await findPlacements({
93:           geoids: strongest(layers, recommendationLayer(campaigns), Object.keys(layers).length),
94:           monthlyBudget: brief.monthlyBudget,
95:         });
96:         update(() => ({ placements: found }));
97:       };
98:       await rankPlacements();
99:       await agent;
100:       await rankPlacements();
101:     } catch (e) {
102:       if (!ctrl.signal.aborted) {
103:         update(() => ({ error: e instanceof Error ? e.message : String(e) }));
104:       }
105:     }
106:   }, []);
107: 
108:   // The experimental cost estimate orders the list cheapest first, so the list,
109:   // the map numbers and the "lowest cost" tag agree; without it the order stays
110:   // by area.
111:   const { cost } = useSettings();
112:   const ordered = useMemo(
113:     () =>
114:       run?.placements && cost
115:         ? { ...run, placements: [...run.placements].sort((a, b) => a.costPerAudienceMember - b.costPerAudienceMember) }
116:         : run,
117:     [run, cost],
118:   );
119: 
120:   return { run: ordered, start };
121: }

